package investigation

// BuildDefensivePlan starts with a user-selected asset/time range and evidence,
// without inventing a vulnerability. An optional finding is handled separately
// by the case snapshot and does not establish that an intrusion occurred.
func BuildDefensivePlan() Plan {
	return Plan{EngineVersion: EngineVersion, Method: "Log evidence-based independent research", Family: "defensive",
		Summary: "Examine observed behavior and normal alternatives in actual logs for selected subjects/periods.",
		Hypotheses: []Hypothesis{
			{ID: "path_access", Title: "Access records for scope of investigation", Statement: "Check the access recorded in the log. Access records alone do not confirm an attack or breach.", RequiredLogs: []string{"Request/audit log for selected target"}, RequiredFields: []string{"time", "Target", "Path or event type"}, Hunt: "Check events that match the investigation target, period, and path and classify registered ARTEX verification requests.", BenignAlternatives: []string{"normal user activity", "Approved security check", "Operation/monitoring work"}, NextSteps: []string{"Compare original events with approved action history."}},
			{ID: "multi_path", Title: "Request flow from the same log origin", Statement: "Review multiple route requests from the same source, destination, session, or origin. The same actor is not confirmed just by the same IP.", RequiredLogs: []string{"Web request/session log"}, RequiredFields: []string{"time", "Target", "channel", "Session or departure point"}, Hunt: "Check different route requests from the same source within 10 minutes and compare them with normal resource loading.", BenignAlternatives: []string{"Normal browser request", "NAT/Shared Proxy", "approved inspection"}, NextSteps: []string{"Review request flow with session, account, and operation history."}},
			{ID: "additional_evidence", Title: "Basis for alerts and follow-up actions", Statement: "A distinction is made between the alert itself and a successful attack. Authentication, host, and network activities are reviewed when the corresponding original logs are available.", RequiredLogs: []string{"alert source", "Required authentication, host, and network logs"}, RequiredFields: []string{"time", "Target", "Event type", "Account or Session"}, Hunt: "Verify the original alert and note any additional logs and scope of investigation required.", BenignAlternatives: []string{"false positive detection", "Approved Administrative Actions"}, NextSteps: []string{"Don't assume logs that don't exist; get the data you need."}},
		}, Limitations: []string{"This record is an independent defense investigation initiated without a vulnerability assessment.", "Static analysis compiles in-scope events and limited request flows and does not confirm infringement.", "AI investigations are initiated separately and only use read-only evidence within the permitted scope."}}
}
